import { test, expect } from '@playwright/test';

test.describe('Cookie Consent Banner', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display the cookie consent banner on page load', async ({ page }) => {
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).toBeVisible();
  });

  test('should disappear after accepting the cookie consent', async ({ page }) => {
    const acceptButton = page.getByRole('button', { name: /accept/i });
    await acceptButton.click();

    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).toBeHidden();
  });
});
